class HRManagementSystem:
    VALID_EMPLOYEE_FIELDS = {'name', 'position', 'department', 'salary'}
    NOT_FOUND = False

    def __init__(self):
        self.employees = {}

    def add_employee(self, employee_id, name, position, department, salary):
        if self._employee_exists(employee_id):
            return False
        self.employees[employee_id] = {
            'name': name,
            'position': position,
            'department': department,
            'salary': salary
        }
        return True

    def remove_employee(self, employee_id):
        if not self._employee_exists(employee_id):
            return False
        del self.employees[employee_id]
        return True

    def update_employee(self, employee_id: int, employee_info: dict):
        employee = self.get_employee(employee_id)
        if employee is self.NOT_FOUND:
            return False
        if not self._is_valid_employee_update(employee_info):
            return False
        self._apply_employee_update(employee, employee_info)
        return True

    def get_employee(self, employee_id):
        return self._get_employee_by_id(employee_id)

    def list_employees(self):
        return self._build_employee_data()

    def _employee_exists(self, employee_id):
        return employee_id in self.employees

    def _is_valid_employee_update(self, employee_info):
        return all(key in self.VALID_EMPLOYEE_FIELDS for key in employee_info)

    def _apply_employee_update(self, employee, employee_info):
        for key, value in employee_info.items():
            employee[key] = value

    def _get_employee_by_id(self, employee_id):
        return self.employees.get(employee_id, self.NOT_FOUND)

    def _build_employee_data(self):
        employee_data = {}
        for employee_id, employee_info in self.employees.items():
            employee_data[employee_id] = self._build_employee_details(employee_id, employee_info)
        return employee_data

    def _build_employee_details(self, employee_id, employee_info):
        details = {'employee_ID': employee_id}
        details.update(employee_info)
        return details
